import unittest
class TestAddr(unittest.TestCase):
    def test_steve(self):
        out = run_student_code(inputs=['Steve', 'Sanders', '91 Station Road', 'London'])
        if "Steve Sanders" not in out:
            self.fail("❌ No encontré el nombre completo 'Steve Sanders' en la salida.")
        if "91 Station Road" not in out:
            self.fail("❌ No encontré la dirección '91 Station Road'.")
        if "London" not in out:
            self.fail("❌ No encontré la ciudad 'London'.")

